+func TestInstanceMetadataClientIsAvailable(t *testing.T) {
+	for _, tc := range []struct {
+		name string
+		body string
+		want bool
+	}{
+		{"short instance ID", "i-1a2b3c4d", true},
+		{"long instance ID", "i-1234567890abcdef0", true},
+		{"captive portal", "<!DOCTYPE html><html>Login</html>", false},
+		{"wrong prefix", "x-12345678", false},
+		{"too short", "i-1234567", false},
+		{"too long", "i-1234567890abcdef01", false},
+		{"uppercase", "i-ABCDEF12", false},
+		{"trailing newline", "i-12345678\n", false},
