+		t.Run(tc.name, func(t *testing.T) {
+			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+				switch r.URL.Path {
+				case "/latest/api/token":
+					fmt.Fprint(w, "test-token")
+				case "/latest/meta-data/instance-id":
+					fmt.Fprint(w, tc.body)
+				default:
+					t.Errorf("unexpected metadata path: %s", r.URL.Path)
+					http.NotFound(w, r)
+				}
+			}))
+			defer server.Close()
+
+			client, err := NewInstanceMetadataClient(context.Background(), WithIMDSClient(imds.New(imds.Options{Endpoint: server.URL})))
+			if err != nil {
+				t.Fatal(err)
+			}
+			if got := client.IsAvailable(context.Background()); got != tc.want {
+				t.Errorf("IsAvailable() = %v, want %v", got, tc.want)
+			}
+		})
+	}
+}
+
+func TestInstanceMetadataClientIsAvailableTimeout(t *testing.T) {
+	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		if r.URL.Path == "/latest/api/token" {
+			fmt.Fprint(w, "test-token")
+			return
+		}
+		<-r.Context().Done()
+	}))
+	defer server.Close()
+
+	client, err := NewInstanceMetadataClient(context.Background(), WithIMDSClient(imds.New(imds.Options{Endpoint: server.URL})))
+	if err != nil {
+		t.Fatal(err)
+	}
+	start := time.Now()
+	if client.IsAvailable(context.Background()) {
+		t.Fatal("timed out metadata request reported available")
+	}
+	if elapsed := time.Since(start); elapsed > time.Second {
+		t.Errorf("availability check took %v, want at most one second", elapsed)
+	}
+}
+
+func TestInstanceMetadataClientOptionError(t *testing.T) {
+	want := errors.New("invalid option")
+	_, err := NewInstanceMetadataClient(context.Background(), func(*InstanceMetadataClient) error { return want })
+	if !errors.Is(err, want) {
+		t.Errorf("NewInstanceMetadataClient error = %v, want %v", err, want)
+	}
+}
